def f(g):
    from collections import deque
    H,W=len(g),len(g[0]); seen=set(); out=[r[:] for r in g]
    bg=collections.Counter(v for r in g for v in r).most_common(1)[0][0]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[i][j] and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                newc={2:3,3:2,4:1}[len(c)]
                for y,x in c: out[y][x]=newc
    return out
